import sys
from math import sqrt

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    m = int(input_data[1])

    points = []
    for x in range(n + 1):
        for y in range(m + 1):
            if x + y == 0:
                continue

            valid = True
            for px, py in points:
                dx = x - px
                dy = y - py
                dist_sq = dx*dx + dy*dy
                root = int(sqrt(dist_sq))
                if root * root == dist_sq:
                    valid = False
                    break

            if valid:
                points.append((x, y))

    print(len(points))
    for x, y in points:
        print(f"{x} {y}")

if __name__ == "__main__":
    main()
